{
  "avaliacoes": [
    {
      "id": "E81f378e923074656",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Em instalações flutuantes, a agitação dos fluidos dentro de vasos separadores pode perturbar a separação e provocar alarmes incorretos de nível, com possibilidade de parada de produção.",
          "trechos": [
            "E81f378e923074656:689:1380"
          ],
          "condicoes": [
            "instalações offshore flutuantes, especialmente FPSO",
            "condições marítimas adversas",
            "vasos separadores instalados na planta de processamento primário"
          ],
          "limites": [
            "o trecho descreve mecanismo e consequência operacional, sem quantificar frequência ou severidade",
            "não estabelece critério de projeto nem requisito normativo"
          ]
        },
        {
          "proposicao": "Tecnologias ciclônicas são apresentadas como alternativa para minimizar perda de desempenho na separação e descontrole do nível de interface, porque seu desempenho seria independente do movimento da embarcação devido à alta aceleração centrífuga interna.",
          "trechos": [
            "E81f378e923074656:1380:2073"
          ],
          "condicoes": [
            "emprego de tecnologias ciclônicas em substituição a parte dos vasos separadores",
            "cenário com movimento da embarcação afetando separadores convencionais"
          ],
          "limites": [
            "o texto usa expectativa e potencial de minimização, não garantia universal",
            "valores numéricos estão apagados e não podem ser reconstruídos",
            "não informa desempenho comparativo em todas as condições operacionais"
          ]
        },
        {
          "proposicao": "A substituição de alguns vasos por ciclones pode reduzir a quantidade de instrumentos e dispositivos associados ao controle de nível e, em alguns casos, até dispositivos de alívio de pressão, com impacto em custos de compra, instalação e manutenção.",
          "trechos": [
            "E81f378e923074656:1380:2073",
            "E81f378e923074656:2073:2274"
          ],
          "condicoes": [
            "substituição de alguns vasos separadores por equipamentos ciclônicos",
            "casos em que o novo equipamento é suficientemente pequeno"
          ],
          "limites": [
            "trata-se de efeito potencial associado a uma mudança tecnológica específica",
            "não substitui avaliação de segurança de processo ou requisitos aplicáveis",
            "não traz critérios para eliminar instrumentos ou alívio em instalações brasileiras"
          ]
        }
      ]
    },
    {
      "id": "Eb4d1f515d5eaf16f",
      "pertinente": true,
      "tipo": "resultado_experimental",
      "achados": [
        {
          "proposicao": "No separador tubular de pequeno diâmetro, a interface deve ser mantida aproximadamente na região central; caso contrário, o desempenho da separação óleo-água pode ser comprometido.",
          "trechos": [
            "Eb4d1f515d5eaf16f:0:692"
          ],
          "condicoes": [
            "separador tubular com 12 polegadas de diâmetro",
            "controle do nível de interface óleo-água"
          ],
          "limites": [
            "aplicação direta ao arranjo SSAO e ao equipamento testado",
            "não fornece banda admissível nem regra geral para todos os separadores trifásicos"
          ]
        },
        {
          "proposicao": "A qualificação do sistema de controle buscou verificar robustez suficiente para manter a interface na faixa requerida em operação normal, sob flutuações de carga e em condições transientes como partidas, paradas e flushing.",
          "trechos": [
            "Eb4d1f515d5eaf16f:0:692",
            "Eb4d1f515d5eaf16f:692:1386"
          ],
          "condicoes": [
            "tempos de ação e retardo de instrumentação, malha e comunicação similares aos esperados em operação real do SSAO",
            "flutuações de vazão, pressão e composição",
            "transientes operacionais"
          ],
          "limites": [
            "os objetivos de qualificação não equivalem, por si, a comprovação universal de desempenho",
            "não detalha sintonia, lógica completa nem critérios quantitativos de aceitação"
          ]
        },
        {
          "proposicao": "A matriz de testes para o controle incluiu perturbações de alimentação, bloqueio de saídas, variações em degrau e oscilatórias, aumento de atraso de malha e golfadas; também foi testada estratégia de Dead Band Assimétrico.",
          "trechos": [
            "Eb4d1f515d5eaf16f:1386:2084",
            "Eb4d1f515d5eaf16f:2084:2187"
          ],
          "condicoes": [
            "programa de qualificação do sistema de controle",
            "análise da estabilidade e da resposta a flutuações"
          ],
          "limites": [
            "o trecho apenas descreve o escopo dos testes e a estratégia avaliada",
            "não informa neste ponto os resultados quantitativos nem a configuração completa da estratégia"
          ]
        }
      ]
    },
    {
      "id": "E2624d619edec56ee",
      "pertinente": true,
      "tipo": "resultado_experimental",
      "achados": [
        {
          "proposicao": "Ocorreram problemas de implementação e instrumentação nos testes, como ausência inicial de associação do trip por nível baixo ao medidor em teste, falta de anti-windup no Dead Band Assimétrico e bugs de lógica, mas foi concluído que isso não afetou significativamente a qualificação do sistema de controle.",
          "trechos": [
            "E2624d619edec56ee:0:700",
            "E2624d619edec56ee:1397:2092"
          ],
          "condicoes": [
            "durante os testes de qualificação do sistema de controle",
            "ambiente de testes com falhas de programação e ajustes"
          ],
          "limites": [
            "a conclusão de não impacto significativo refere-se a essa campanha de qualificação",
            "o trecho não permite generalizar que tais falhas sejam sempre aceitáveis"
          ]
        },
        {
          "proposicao": "A bomba que simulava a produção de água operava próxima da vazão máxima e, em alguns testes com vazões superiores ao limite apagado, o controle se tornava instável, dificultando ou inviabilizando o estabelecimento de condição estável.",
          "trechos": [
            "E2624d619edec56ee:700:1397"
          ],
          "condicoes": [
            "testes que exigiam vazões superiores ao valor não legível",
            "bomba de água próxima de sua capacidade máxima"
          ],
          "limites": [
            "o valor de vazão está apagado e não pode ser reconstruído",
            "a limitação é do arranjo de teste, não necessariamente da operação real"
          ]
        },
        {
          "proposicao": "Os registros de teste acompanharam variáveis como fluxo de entrada de água, velocidade da bomba, nível de interface e nível de óleo, incluindo situação de parada súbita das bombas de alimentação.",
          "trechos": [
            "E2624d619edec56ee:1397:2092",
            "E2624d619edec56ee:2092:2169"
          ],
          "condicoes": [
            "situações de teste selecionadas",
            "monitoramento de variáveis de processo e de atuação"
          ],
          "limites": [
            "o trecho indica quais variáveis foram observadas, mas não traz os resultados completos",
            "não informa interação com malha de pressão no mesmo nível de detalhe"
          ]
        }
      ]
    },
    {
      "id": "E07bef9e0e720fba9",
      "pertinente": true,
      "tipo": "resultado_experimental",
      "achados": [
        {
          "proposicao": "Nos testes, algumas diferenças em relação ao campo permaneceram: os volumes reais do pipe separator e do outlet vessel eram maiores que os testados, tornando os testes conservativos sob esse aspecto.",
          "trechos": [
            "E07bef9e0e720fba9:700:1395"
          ],
          "condicoes": [
            "comparação entre circuito de testes e situação real de campo"
          ],
          "limites": [
            "a conservatividade mencionada vale apenas para o aspecto de volume",
            "não permite concluir conservatividade global da campanha"
          ]
        },
        {
          "proposicao": "As pressões de teste foram menores que as reais por limitação das janelas de plexiglass, o que tornou os testes não conservativos sob esse aspecto.",
          "trechos": [
            "E07bef9e0e720fba9:1395:2089"
          ],
          "condicoes": [
            "existência de limitação de pressão máxima do aparato de teste"
          ],
          "limites": [
            "não informa a magnitude da diferença de pressão",
            "o resultado experimental deve ser interpretado com essa restrição de representatividade"
          ]
        },
        {
          "proposicao": "A velocidade de variação da rotação da bomba de injeção que controlava o nível foi maior que a real, caracterizando também condição de teste não conservativa.",
          "trechos": [
            "E07bef9e0e720fba9:1395:2089"
          ],
          "condicoes": [
            "comparação entre dinâmica do atuador nos testes e no campo",
            "bomba de injeção usada como elemento de controle de nível"
          ],
          "limites": [
            "o trecho não informa quanto maior era essa velocidade",
            "isso limita a extrapolação direta do comportamento do controle para a operação real"
          ]
        }
      ]
    },
    {
      "id": "Ea80d9330e125649a",
      "pertinente": true,
      "tipo": "resultado_experimental",
      "achados": [
        {
          "proposicao": "Foi testada uma estratégia de Dead Band Assimétrico em que o sistema reagia mais rapidamente à diminuição do nível de interface, com a finalidade de preservar mais eficientemente a qualidade da água de injeção.",
          "trechos": [
            "Ea80d9330e125649a:0:695"
          ],
          "condicoes": [
            "programa de testes do controle de nível de interface",
            "foco em proteção da qualidade da água de injeção"
          ],
          "limites": [
            "o trecho apresenta finalidade e lógica geral, sem detalhar a sintonia",
            "não demonstra que a estratégia seja superior em toda aplicação"
          ]
        },
        {
          "proposicao": "Os testes realizados comprovaram robustez adequada do sistema de controle de nível frente às perturbações de entrada previstas no projeto, sem variações significativas do nível de interface no outlet vessel nessas condições.",
          "trechos": [
            "Ea80d9330e125649a:695:1393"
          ],
          "condicoes": [
            "perturbações de entrada previstas no projeto",
            "bases de projeto fornecidas pela Petrobras"
          ],
          "limites": [
            "a comprovação está condicionada às perturbações previstas no projeto, não a perturbações arbitrárias",
            "não equivale a validação universal para outras geometrias, fluidos ou filosofias de controle"
          ]
        },
        {
          "proposicao": "Nos testes de golfadas, utilizou-se vaso pressurizado com gás cuja pressão era liberada rapidamente no pipe separator, com duração e volume das golfadas controlados pelo inventário e pelo tempo de injeção de gás na linha de líquido.",
          "trechos": [
            "Ea80d9330e125649a:695:1393"
          ],
          "condicoes": [
            "simulação de golfadas em circuito de testes",
            "injeção de gás na linha de líquido"
          ],
          "limites": [
            "descreve o método experimental de geração de golfadas",
            "não prova equivalência completa com todos os regimes de slugging de campo"
          ]
        }
      ]
    },
    {
      "id": "E6444116f8d06c626",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A redução de volume dos equipamentos compactos aumenta a sensibilidade a oscilações; o texto cita os hidrociclones como caso especialmente sensível por terem constante de tempo muito pequena em comparação com separadores.",
          "trechos": [
            "E6444116f8d06c626:0:698"
          ],
          "condicoes": [
            "uso de equipamentos compactos em tratamento de óleo e água offshore",
            "presença de oscilações propagadas a jusante"
          ],
          "limites": [
            "o valor numérico da constante de tempo está apagado",
            "o trecho discute tendência dinâmica, não critério de dimensionamento"
          ]
        },
        {
          "proposicao": "Modelos dinâmicos baseados em balanços de massa, momento e população foram desenvolvidos para separador trifásico e hidrociclone com o objetivo de reproduzir o comportamento dinâmico das principais variáveis e prever tendências de eficiência de separação óleo-água sob slug.",
          "trechos": [
            "E6444116f8d06c626:698:1394"
          ],
          "condicoes": [
            "emprego de modelos fenomenológicos simplificados, porém efetivos",
            "análise de comportamento sob slug"
          ],
          "limites": [
            "o texto fala em prever tendências, não necessariamente valores exatos em qualquer caso",
            "não substitui validação experimental para cada instalação"
          ]
        },
        {
          "proposicao": "O Band Control busca maximizar a capacidade filtrante do separador permitindo maior oscilação do nível dentro de uma banda; fora dela, utiliza parâmetros mais rápidos para retornar o nível aos limites, e foi apresentado como capaz de estabilizar o escoamento para hidrociclones em comparação com PID tradicional.",
          "trechos": [
            "E6444116f8d06c626:1394:2091"
          ],
          "condicoes": [
            "controle do nível de interface de água em separador trifásico acoplado a hidrociclone",
            "existência de banda operacional de níveis permitidos"
          ],
          "limites": [
            "o ganho decorre do estudo comparativo descrito, não de regra universal",
            "o trecho não informa parâmetros de sintonia nem faixa admissível da banda",
            "a aplicação está ligada ao arranjo separador-hidrociclone a jusante"
          ]
        }
      ]
    }
  ],
  "concluir": false,
  "proximas_fontes": [
    "E5a973e6af5f8eb82",
    "E13df42fe7ef6b97b",
    "Ec50bcee212098fe0"
  ],
  "pedidos_busca": [],
  "lacunas": [
    "Interações explícitas entre malha de pressão do separador, válvula de saída de gás e malhas de nível/interface ainda estão pouco documentadas nas fontes avaliadas.",
    "Critérios de seleção e posicionamento de instrumentos de pressão, nível e interface para FPSO não apareceram com detalhe suficiente.",
    "Efeitos de válvulas de saída de óleo, água e gás sobre carryover, carryunder e estabilidade entre malhas carecem de fonte mais direta.",
    "Faltam trechos sobre alarmes, intertravamentos e shutdown relacionados simultaneamente a pressão e níveis em separadores trifásicos de FPSO.",
    "Não há, neste conjunto, detalhes operacionais suficientes sobre sintonia, anti-windup, atrasos de comunicação e limites práticos de atuação aplicáveis além dos testes descritos."
  ]
}
